css:
/* Contenedor padre en lugar de 'body' */
.switch-container {
  background-color: #3b3b3bfd;
  display: flex;
  justify-content: center;
  align-items: center;
  min-height: 10%;
  border-radius: 50px;
  padding: 20px;
}

/* Contenedor principal del Switch */
.switch {
  position: relative;
  display: inline-block;
  width: 200px;
  height: 200px;
}

/* Ocultar el checkbox nativo */
.switch input {
  opacity: 0;
  width: 0;
  height: 0;
}

/* Anillo exterior y base del Knob */
.Knob_1 {
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  bottom: 0;
  border-radius: 50%;
  cursor: pointer;
  background-color: #111;
  /* Arco apagado */
  background-image: radial-gradient(
      circle at center,
      #050505 57%,
      transparent 58%,
      transparent 65%,
      #050505 40%
    ),
    conic-gradient(from -120deg, #333 0deg, #333 240deg, #111 240deg);
  box-shadow:
    0 10px 20px rgba(0, 0, 0, 0.8),
    inset 0 0 10px rgba(0, 0, 0, 0.9);
  transition: all 0.5s ease;
}

.Knob_1::before {
  content: "";
  position: absolute;
  /* Posicionamiento y tamaño de la perilla interior */
  top: 30px;
  left: 30px;
  right: 30px;
  bottom: 30px;
  border-radius: 50%;
  /* Textura de metal cónico */
  background: conic-gradient(
    from 180deg,
    #181818 0%,
    #3a3a3a 25%,
    #181818 50%,
    #3a3a3a 75%,
    #181818 100%
  );
  box-shadow:
    0 0 15px rgba(0, 0, 0, 0.9),
    inset -2px 5px 3px rgba(255, 255, 255, 0.192),
    inset 5px -6px 2px rgb(26, 26, 26);
  transition: transform 0.5s cubic-bezier(0.4, 0, 0.2, 1);
  /* Posición inicial (Girado hacia la izquierda) */
  transform: rotate(-90deg);
}

/* Indicador luminoso (La línea en la perilla) */
.Knob_1::after {
  content: "";
  position: absolute;
  top: 44px;
  left: 96px; /* Centrado (100px - la mitad del ancho de 3px) */
  width: 12px;
  height: 25px;
  background: #444; /* Color apagado */
  border-radius: 4px;
  box-shadow: inset 0 1px 2px rgba(0, 0, 0, 0.8);
  transition: all 1s cubic-bezier(0.4, 0, 0.2, 1);

  /* El eje de rotación se establece en el centro exacto del knob de 200px */
  transform-origin: 3px 60px;
  transform: rotate(-120deg);
}

/* =========================================
   ESTADO ACTIVO (CHECKED)
   ========================================= */

/* Arco iluminado cuando está encendido */
.switch input:checked + .Knob_1 {
  background-image: radial-gradient(
      circle at center,
      #050505 57%,
      transparent 58%,
      transparent 65%,
      #050505 40%
    ),
    conic-gradient(from -120deg, #ff4500 0deg, #ff4500 240deg, #111 240deg);
  box-shadow:
    0 10px 20px rgba(0, 0, 0, 0.8),
    inset 0 0 15px rgba(248, 118, 70, 0.1);
}

/* Rotar el indicador e iluminarlo con neón naranja */
.switch input:checked + .Knob_1::after {
  transform: rotate(120deg);
  background: #ff4500;
  box-shadow:
    0 0 5px #ff4500,
    0 0 15px #ff4500;
}
